\label{lem:valid}
Assume~\ref{S1}--\ref{S2}, and let each $\underline V^{0}_{t}$ be bounded.
\begin{enumerate}[label=(\alph*),nosep]
\item (Strong validity implies~\ref{O3}.) Assume $\underline V^{0}_{t}\le V_t$ for all $t$, and that every cut
created at index $t<T$ during iteration $k$ satisfies $f\le\mathcal{B}_t(\underline V^{k}_{t+1})$ on
$X_t$; this is the validity notion of TFDP \citep[Assumption~4(ii)]{forcier2023trajectory}
and of stochastic Lipschitz dynamic programming (SLDP) \citep[eq.~(20)]{ahmed2022sldp}. Then every cut is below $V_t$ on $X_t$, so~\ref{O3}
holds with $U_t=V_t$. If moreover $\underline V^{0}_{t}\le\mathcal{B}_t(\underline V^{0}_{t+1})$, then $\underline V^{k}_{t}\le\mathcal{B}_t(\underline V^{k}_{t+1})$ on
$X_t$ for all $k\ge0$, so that $r^k_t\ge0$ for all $k\ge1$.
\item (Tightness for the updated approximation implies~\ref{O2}.) If
$f^k_t(x)\ge\mathcal{B}_t(\underline V^{k}_{t+1})(x)-\bm{\gamma}^k_t$ at $x=\bm{x}^k_t$ and
$\underline V^{k}_{t+1}\ge\underline V^{k-1}_{t+1}$, then~\ref{O2} holds.
\end{enumerate}

\label{lem:basic}
Under \cref{ass:S,ass:O}, we have, for all $k\ge1$ and $t<T$:
\begin{enumerate}[label=(\roman*),nosep]
\item $\underline V^{k}_{t}$ is Borel and $L_t$-Lipschitz for $\operatorname{dist}_t$, and
$\underline V^{0}_{t}\le\underline V^{k-1}_{t}\le\underline V^{k}_{t}\le\bar U_{t}$ on $X_t$, where $\bar U_{t}$ is the Lipschitz envelope of the ceiling~\ref{O3};
\item the residual $r^k_t$ of~\eqref{eq:setting:residuals} is bounded on $X_t$, uniformly in $k$;
\item $V^{\pi^k}_0(x_0)\ge V_0(x_0)$.
\end{enumerate}

\label{lem:lift}
Assume the volume-growth condition~\eqref{eq:setting:volume_growth}.
Let $V,W:X_t\to\mathbb{R}$ be Borel and $L_t$-Lipschitz for $\operatorname{dist}_t$, with
$W\ge V$, and let $x\in X_t$ and $s\ge0$ satisfy $W(x)\ge V(x)+s$. Then
\begin{equation}\label{eq:main:lift_volume}
\int(W-V)\,d\mu_t\ \ge\ \kappa_t\,\varphi_t(s),\quad \text{where}\quad 
\varphi_t(s):=\frac s2\min\Big\{1,\Big(\frac{s}{4L_tD_t}\Big)^{d_t}\Big\},
\end{equation}
with $s/(4L_tD_t):=\infty$ if $L_t=0$. If $d_t=0$, the bound improves to $\kappa_ts$.

\label{cor:uniform}
In the setting of \cref{thm:master}(a), assume $L_t\le L$, $D_t\le D$ and $\kappa_t\ge\kappa$, an initial
error at most $\bar\ell$ per stage, $U_t=V_t$ and deterministic errors, and let $\varepsilon\le4LD$. Then
$\Psi_T(g)\ge\kappa T\psi(g/T)$, where $\psi$ is $\hat\psi_t$ with $\rho=4LD$, and
\begin{equation}\label{eq:main:rate_relative}
\mathbb{E}\,\#\{k\ge1:G^k>T\varepsilon+\Gamma\}\le\frac{(d+1)\,\bar\ell\,(T+1)\,(4LD)^d}{\kappa\,\varepsilon^{d+1}}.
\end{equation}

\label{cor:disc}
Let the stage-$t$ loss be $\beta^{t-1}\hat\ell_t$ with $0<\beta<1$ and $\hat\ell_t$ taking values in an
interval $[a_t,a_t+\bar\ell]$, let $\underline V^{0}_{t}$ be the constant $\sum_{s>t}\beta^{s-1}a_s$ (e.g.\ $\hat\ell_t\in[0,\bar\ell]$
and $\underline V^{0}_{}=0$), let the cuts of index $t$ be $\beta^{t}\hat L$-Lipschitz, $X_t$ convex ($\kappa_t=1$),
$D_t\le D$, cuts valid and exact ($U=V$, $\gamma=\gamma^F=0$), and $(1-\beta)\varepsilon\le4\hat L D$.
Then, for every horizon $T$,
\begin{equation}\label{eq:main:rate_discounted}
\mathbb{E}\,\#\{k\ge1:G^k>\varepsilon\}\le\frac{2(d+1)\,\bar\ell\,(4\hat L D)^d}{(1-\beta)^{d+2}\,\varepsilon^{d+1}} .
\end{equation}

\label{cor:cover}
In the setting of \cref{thm:master}(b) for~(a) and of \cref{thm:master}(c) for~(b), with initial error at most
$\bar\ell$ per stage and $U_t=V_t$:
\begin{enumerate}[label=(\alph*),nosep]
\item if $L_t\le L$ and $X_t$ has $\sigma$-nets of size at most $Z(1+2D/\sigma)^d$ for every
$\sigma>0$ (\cref{lem:nets}; $Z\ge\max_t|Z_t|$ bounds the number of discrete configurations, $Z=1$ for convex $X_t$), then
\begin{equation}\label{eq:main:covering_rate_relative}
\mathbb{E}\,\#\{k\ge1:G^k>T\varepsilon+\Gamma\}\le Z\bar\ell\,(T+1)(1+8LD/\varepsilon)^d/\varepsilon ;
\end{equation}
\item if every $X_t$ is finite, $\mathbb{E}\sum_k(G^k-\Gamma)_+\le\bar\ell\sum_{t<T}(T-t)|X_t|$, hence
$\mathbb{E}\,\#\{k\ge1:G^k>\theta+\Gamma\}\le\bar\ell\,T(T+1)\max_t|X_t|/(2\theta)$.
\end{enumerate}

\label{rem:absolute}
Replacing $\varepsilon$ with $\varepsilon/T$ in~\eqref{eq:main:rate_relative} gives, for $\varepsilon\le4LDT$,
\begin{equation}\label{eq:main:rate_absolute}
\mathbb{E}\,\#\{k\ge1:G^k>\varepsilon+\Gamma\}\le\frac{(d+1)\,\bar\ell\,T^{d+1}(T+1)\,(4LD)^d}{\kappa\,\varepsilon^{d+1}},
\end{equation}
where the extra factor $T^{d+1}$ only reflects the per-stage error $\varepsilon/T$. With the constants of
\cref{rem:lipT}, the same substitution in~\eqref{eq:main:rate_growing_lipschitz} gives the bound
$2(d+1)\,\bar\ell\,(4\tilde LD)^d\,\bar w^{\,d+1}/\varepsilon^{d+1}$, and that of \citet[Thm.~2]{zhang2022stochastic}, with
per-stage tolerances $\varepsilon/T$, is $\sum_{t<T}(1+2(T-t)\tilde LDT/\varepsilon)^d$. \Cref{cor:cover}(a) converts likewise.

\label{prop:benders}
Fix a norm and, for $\eta>0$, let $X^\eta_t:=\{x\in\operatorname{aff} X_t:\operatorname{dist}(x,X_t)\le\eta\}$.
Assume:
\begin{itemize}[nosep]
\item $\emptyset\ne \mathcal{X}_{t+1}(x,\xi)\subset X_{t+1}$ for $x\in X^\eta_t$ and $t<T$ (extended relatively
complete recourse), and~\ref{S2} and~\ref{S3} hold with $X^\eta_t$ in place of $X_t$ as the set of incoming
states;
\item $X_t$ is convex, the graph of $\mathcal{X}_{t+1}(\cdot,\xi)$ over $X^\eta_t$ is convex and $\ell_{t+1}(\cdot,\cdot,\xi)$ is
jointly convex on it;
\item the approximations are convex, with $\underline V^{0}_{t}\le V_t$ and $\underline V^{0}_{t}\le\mathcal{B}_t(\underline V^{0}_{t+1})$;
\item every cut is a Benders cut $f^k_t(y)=h(x)+\langle g,y-x\rangle$ of
$h:=\mathcal{B}_t(\underline V^{k}_{t+1})$ at $x=\bm{x}^k_t$, with $g$ a subgradient of the restriction of $h$
to $\operatorname{aff} X_t$.
\end{itemize}
Then $V_t=\mathcal{B}_t(V_{t+1})$ is bounded on $X^\eta_t$, such $g$ exist, and the cuts are valid on $X^\eta_t$, exact
($\gamma=0$), and $L_t$-Lipschitz on $X_t$ with
\begin{equation}\label{eq:inst:benders_lipschitz}
L_t\le\Big(\sup_{X^\eta_t}V_t-\inf_{X_t}\underline V^{0}_{t}\Big)\Big/\eta .
\end{equation}
If $\underline V^{0}_{t}=\sum_{s>t}a_s$ and each $\ell_s$ takes values in $[a_s,a_s+\bar\ell]$ for incoming states in $X^\eta_{s-1}$
(not only in $X_{s-1}$), this is at most $(T-t)\bar\ell/\eta$.
So \cref{ass:O} holds with $U_t=V_t$, provided $\underline V^{0}_{t}$ is also $L_t$-Lipschitz (e.g.\ $\underline V^{0}_{t}$ constant).

\label{thm:ZS}
Consider Algorithm~3 under their Assumptions~1--3 and the parameter bounds of \cref{prop:ZS}, with scenario
paths sampled stage by stage from the transition probabilities, independently across stages and iterations
(for uniform transition probabilities, their Assumption~4 implies this). Assume that, for $1\le s<T$, the
approximations of index $s$ are $L$-Lipschitz, $X_s$ has dimension at most $d$ and lies in a ball of
diameter $D$, nodal costs lie in $[0,\bar\ell]$, and $V_s\le(T-s)\bar\ell$ on $X_s$. Then
\begin{equation}\label{eq:inst:zs_bound_uniform}
\mathbb{E}[\iota]\le\bar\ell\,T(T+1)\,\big(1+8LD(T-1)/\varepsilon\big)^d/\varepsilon .
\end{equation}

\label{prop:SDDiP}
Consider SDDiP \citep{zou2019sddip} with binary states $X_t\subset\{0,1\}^{n_t}$, mixed-integer linear
nodal problems with compact feasible sets, solved exactly, complete continuous recourse, losses in $[0,\bar\ell]$, $\underline V^{0}_{}=0$, and forward scenarios sampled from the tree's
distribution. Use, at each index $t<T$, a Lagrangian cut with an optimal multiplier or an integer optimality
cut; other valid cuts, such as strengthened Benders cuts, may be added. Then
\cref{thm:master}(c) applies with $U_t=V_t$ and $\Gamma=0$:
\begin{equation}\label{eq:inst:sddip_bound}
\mathbb{E}\sum_{k\ge1}G^k\ \le\ \bar\ell\sum_{t<T}(T-t)|X_t|\ \le\ 2^{n}\bar\ell\,\frac{T(T+1)}2,\qquad n:=\max_{t<T}n_t,
\end{equation}
and, for $\delta\in(0,1]$, with probability at least $1-\delta$, $\sum_kG^k\le9\ln(3/\delta)\,2^{n-1}\bar\ell\,T(T+1)$.

\label{thm:saa}
Let \cref{ass:S} hold for both laws, with $\Xi_t$ carrying $\mathbb{P}_t$ and $\widehat{\mathbb{P}}_t$, and assume~\eqref{eq:setting:volume_growth}. Let
$G^k=V^{\pi^k}_0(x_0)-\underline V^{k-1}_{0}(x_0)$, where $V^{\pi^k}_0$ is the expected cost under the \emph{true} laws, and let $\Psi_T$ be the aggregated lift function of
\cref{sec:lemmas} and $\bm{\Gamma}^F_k$ the forward-error sum~\eqref{eq:main:error_sums}. Then,
conditionally on $\widehat{\mathbb{P}}$,
\begin{equation}\label{eq:noise:saa_master}
\mathbb{E}\Big[\sum_{k\ge1}\Psi_T\Big(\Big(G^k-\bm{\Gamma}^F_k-\sum_{t<T}(\Delta^+_t)_+\Big)_+\Big)\Big]\le\sum_{t<T}\hat M_t,
\end{equation}
the high-probability statement of \cref{thm:master}(a) holds with $\hat M_t$ in place of $M_t$, and,
for every $k\ge1$,
\begin{equation}\label{eq:noise:saa_accuracy}
V_0(x_0)-\underline V^{k-1}_{0}(x_0)\le G^k,\qquad V^{\pi^k}_0(x_0)-V_0(x_0)\le G^k+\sum_{t<T}(\Delta^-_t)_+ .
\end{equation}

\label{cor:wasserstein}
\begin{enumerate}[label=(\alph*),nosep]
\item Let $\Xi_{t+1}$ be a subset of a normed space and $\mathsf W_1$ the Wasserstein-1 distance for its norm.
If, for all $x\in X_t$ and $W\in\mathcal{W}_{t+1}\cup\{V_{t+1}\}$, the map
$\xi\mapsto \dot{\mathcal{B}}_t(W;x,\xi)$ is $L^\xi_t$-Lipschitz on $\Xi_{t+1}$, then
$\Delta^\pm_t\le L^\xi_t\,\mathsf W_1(\mathbb{P}_{t+1},\widehat{\mathbb{P}}_{t+1})$. Hence, with $\Delta_{\rm W}:=\sum_{t<T}L^\xi_t\mathsf W_1(\mathbb{P}_{t+1},\widehat{\mathbb{P}}_{t+1})$,
\begin{equation}\label{eq:noise:saa_wasserstein}
\mathbb{E}\Big[\sum_{k\ge1}\Psi_T\big((G^k-\bm{\Gamma}^F_k-\Delta_{\rm W})_+\big)\Big]\le\sum_{t<T}\hat M_t,\qquad
V^{\pi^k}_0(x_0)-V_0(x_0)\le G^k+\Delta_{\rm W} .
\end{equation}
\item If, for these $x$ and $W$, $\dot{\mathcal{B}}_t(W;x,\cdot)$ takes values in an interval of length $\mathrm{rg}_t$,
then $\Delta^\pm_t\le\mathrm{rg}_t\,\mathrm{TV}(\mathbb{P}_{t+1},\widehat{\mathbb{P}}_{t+1})$, where $\mathrm{TV}(\mathbb{P},\widehat{\mathbb{P}}):=\sup_A|\mathbb{P}(A)-\widehat{\mathbb{P}}(A)|$.
\end{enumerate}

\label{lem:pass}
Let \cref{ass:Sinf,ass:Oinf} hold and~\eqref{eq:setting:volume_growth} hold on $X$, for $\operatorname{dist}$, with constants
$(\mu,\kappa,D,d)$. Let $\Phi^k:=\int(\underline V^{k}-\underline V^{0})\,d\mu$ and $s^k_t:=(r^k(\bm{x}^k_t)-\gamma_{k,t})_+$. In variants~(D)
and~(G), for every $k\ge1$,
\begin{equation}\label{eq:inf:pass_lift}
\Phi^k-\Phi^{k-1}\ \ge\ \kappa\max_{t<\tau_k}\hat\varphi\big(s^k_t\big)\ \ge\ \kappa\hat\psi\big(\bar s^k\big),
\qquad \bar s^k:=\max_{t<\tau_k}s^k_t,
\end{equation}
and $0=\Phi^0\le\Phi^{k-1}\le\Phi^k\le\bar M_U:=\int(\bar U-\underline V^{0})\,d\mu\le M_U$.

\label{rem:tight}
In \cref{thm:master-ih}(a), one factor $(1-\beta)^{-1}$ comes from the potential and $(1-\beta)^{-(d+1)}$ from evaluating
$\hat\psi$ at $(1-\beta)\varepsilon$, that is, from the maximum over the pass. The factor $1-\beta$ inside $\hat\psi$ cannot be
removed from a bound of this convex-regret form (\cref{prop:tight}, for $d=1$): a value error of order $r_0$ can cause a
policy error $r_0/(1-\beta)$, the classical loss of greedy policies \citep{singh1994upper}. Whether the \emph{count}
of bad iterations can avoid it is open.

\label{thm:periodic}
Under \cref{ass:Sinf,ass:Oinf} and~\eqref{eq:setting:volume_growth} phase by phase, the periodic algorithm with
geometric pass lengths satisfies:
\begin{enumerate}[label=(\roman*),nosep]
\item $G^k=\mathbb{E}_{k-1}\big[\sum_{t<\tau_k}(r^k_{p(t)}(\bm{x}^k_t)+e_t)\big]$, with $e_t\in[0,\gamma^F_k]$, and
$G^k\ge\max\{V^{\pi^k}_0(x_0)-V_0(x_0)-\zeta,\,V_0(x_0)-\underline V^{k-1}_0(x_0)\}$;
\item $\mathbb{E}\sum_{k\ge1}\kappa\,\chi_S\big((G^k-\Gamma^\beta_k)_+\big)\le\bar M_U$, with
$\chi_S(g)\ge\hat\psi((1-\beta)g)$ defined in~\eqref{eq:appD:periodic_chi}; with $q_S:=S(1-\beta)/(1-\beta^S)$
and $\Gamma^\beta_k\le\Gamma^\beta$ deterministic, for every $\theta>0$ with $(1-\beta)\theta\le\hat\rho$,
\begin{equation}\label{eq:inf:periodic_rate}
\mathbb{E}\,\#\{k\ge1:G^k>\theta+\Gamma^\beta\}\le\frac{2(d+1)\,\bar M_U\,\hat\rho^d}{\kappa\,(1-\beta)^{d+1}\theta^{d+1}}\min\Big\{1,\frac{q_S^{d+1}}{S}\Big\};
\end{equation}
\item for $\delta\in(0,1]$, with probability at least $1-\delta$, simultaneously for all $\theta>0$,
$\#\{k\ge1:G^k>\theta+\Gamma^\beta_k\}\le9\ln(3/\delta)\,\bar M_U/(\kappa\chi_S(\theta))$.
\end{enumerate}

\label{thm:geom}
Under \cref{ass:I}, \cref{ass:Oinf} holds with $U=V$, $\gamma_{k,t}=0$, the Euclidean distance
and $\hat L$ of~\ref{I4}, and~\eqref{eq:setting:volume_growth} with $\kappa=1$ (\cref{lem:VG}(a)); moreover $r^k\ge0$,
$\zeta=0$ and $\bar M_U\le\bar M:=\operatorname*{avg}_X(V-\underline V^{0})\le\bar\ell/(1-\beta)$. Hence variant~(G) satisfies:
\begin{enumerate}[label=(\roman*),nosep]
\item $G^k=\mathbb{E}_{k-1}\big[\sum_{t<\tau_k}r^k(\bm{x}^k_t)\big]$ and
$G^k\ge\max\{V^{\pi^k}(x_0)-V(x_0),\,V(x_0)-\underline V^{k-1}(x_0)\}\ge0$;
\item $\mathbb{E}\sum_{k\ge1}\hat\psi((1-\beta)G^k)\le\bar M$, and, for every $\varepsilon>0$ with
$(1-\beta)\varepsilon\le\hat\rho$,
\begin{equation}\label{eq:inf:geometric_rate}
\mathbb{E}\,\#\{k\ge1:G^k>\varepsilon\}\le\frac{2(d+1)\,\bar M\,\hat\rho^d}{(1-\beta)^{d+1}\varepsilon^{d+1}}
\le\frac{2(d+1)\,\bar\ell\,(4\hat L D)^d}{(1-\beta)^{d+2}\varepsilon^{d+1}};
\end{equation}
\item for $\delta\in(0,1]$, with probability at least $1-\delta$, for all $\varepsilon>0$, $\#\{k\ge1:G^k>\varepsilon\}\le K_\varepsilon:=9\ln(3/\delta)\,\bar M/\hat\psi((1-\beta)\varepsilon)$
and $V(x_0)-\underline V^{k}(x_0)\le\varepsilon$ for all $k\ge K_\varepsilon$.
\end{enumerate}

\label{prop:lipiter}
Assume \ref{I1}--\ref{I3} and~\ref{Ieta}, and let $\underline V^{0}$ be $L_0$-Lipschitz on $X$. In variants~(D) and~(G):
\begin{enumerate}[label=(\roman*),nosep]
\item every cut is $\bar\ell/((1-\beta)\eta)$-Lipschitz on $X$, so~\ref{I4} holds with
$\hat L=\max\{L_0,\bar\ell/((1-\beta)\eta)\}$;
\item if $(R_{m,\chi})$ holds with $\chi<\eta$ and $L_0\le m\bar\ell/(\eta-\chi)$ (e.g.\@\xspace $\underline V^{0}=0$), every cut is
$m\bar\ell/(\eta-\chi)$-Lipschitz, so~\ref{I4} holds with $\hat L=m\bar\ell/(\eta-\chi)$, \emph{uniformly in $\beta$};
\item under $(R_{1,0})$, every cut is $\bar\ell/\eta$-Lipschitz, so~\ref{I4} holds with $\hat L=\max\{L_0,\bar\ell/\eta\}$.
\end{enumerate}

\label{cor:rel}
Under \ref{I1}--\ref{I3} and~\ref{Ieta} with $\underline V^{0}=0$ and $(R_{m,0})$, variant~(G) satisfies, for
$\varepsilon_{\rm rel}\le4mD/\eta$,
\begin{equation}\label{eq:inf:relative_rate}
\mathbb{E}\,\#\Big\{k:G^k>\varepsilon_{\rm rel}\frac{\bar\ell}{1-\beta}\Big\}\le\frac{2(d+1)\,(4mD/\eta)^d}{(1-\beta)\,\varepsilon_{\rm rel}^{d+1}},
\end{equation}
with $1/(1-\beta)$ cuts per iteration in expectation. With the crude constant of
\cref{prop:lipiter}(i), the right-hand side is $2(d+1)(4D/\eta)^d/((1-\beta)^{d+1}\varepsilon_{\rm rel}^{d+1})$, for
$\varepsilon_{\rm rel}\le4D/((1-\beta)\eta)$.

\label{rem:regret}
In the setting of \cref{cor:uniform} with $\gamma=\gamma^F=0$ and $\kappa=1$, \cref{lem:valid}(a) and
\cref{lem:gap} give $0\le G^k\le M^V:=\sum_{t<T}\sup_{X_t}(V_t-\underline V^{0}_{t})$. The function $\psi$ of \cref{cor:uniform},
with $\rho=4LD$, satisfies $\psi(s)\ge s^{d+1}/(2(d+1)s_{\max}^d)$ on $[0,s_{\max}]$ when $s_{\max}\ge\rho$. Hence
$\Psi_T(g)\ge g^{d+1}/(2(d+1)T^d\max\{\rho,M^V/T\}^d)$ for $g\le M^V$, and Hölder's inequality with the master
bound~\eqref{eq:main:master_volume} gives
\begin{equation}\label{eq:appA:average_gap}
\mathbb{E}\sum_{k\in[K]}G^k\le K^{d/(d+1)}\big(2(d+1)T^d\max\{\rho,M^V/T\}^d\,M^V\big)^{1/(d+1)} .
\end{equation}

\label{thm:steps}
Let \cref{ass:S} hold, with losses in $[0,\bar\ell]$ and $\underline V^{0}_{t}\equiv0$ for $t<T$. Fix $\omega>0$ and let
$X^+_t:=X_t+[0,\omega]^{n_t}$. Let every cut be a step cut $f(y)=v\,\mathbf 1\{y<x+\omega\mathbf 1\}$ as in \cref{sec:midas},
extended to $\mathbb{R}^{n_t}$ by the same formula, with $\mathcal{B}_t(\underline V^{k-1}_{t+1})(x)-\gamma_t\le v\le\mathcal{B}_t(\underline V^{k}_{t+1})(x)$ at
$x=\bm{x}^k_t$, and let the update be monotone. Let the forward pass be as in \cref{sec:algo}, with no snapping. Then
\begin{equation}\label{eq:appB:midas_bound}
\mathbb{E}\sum_{k\ge1}(G^k-\Gamma)_+\ \le\ \bar\ell\sum_{t<T}(T-t)\frac{\operatorname{vol}(X^+_t)}{\omega^{n_t}}
\ \le\ \bar\ell\,\frac{T(T+1)}2\Big(1+\frac D\omega\Big)^{n},
\end{equation}
where the last bound holds if each $X_t$ lies in a box of side $D$ and $n_t\le n$. If moreover each $X_t$ is a box,
$V_t$ is nonincreasing, and $|V_t(x)-V_t(y)|\le\varepsilon$ when $\|x-y\|_\infty<\omega$
\citep[Prop.~1]{philpott2020midas}, then $\underline V^{k}_{t}\le V_t+(T-t)\varepsilon$ on $X_t$, so
$V^{\pi^k}_0(x_0)-V_0(x_0)\le G^k+T\varepsilon$.

\label{lem:std}
Under \cref{ass:Sinf}:
(i) for $W,W'\in\mathfrak M$, $\mathcal{B} W$ is Borel and bounded, $W\le W'$ implies $\mathcal{B} W\le\mathcal{B} W'$, $\mathcal{B}(W+c)=\mathcal{B} W+\beta c$ for
constants $c$, so $\sup|\mathcal{B} W-\mathcal{B} W'|\le\beta\sup|W-W'|$; and $\mathfrak M$ is closed under uniform convergence;
(ii) $0\le V\le\bar\ell/(1-\beta)$, $V$ is the only bounded fixed point of $\mathcal{B}$ in $\mathfrak M$, every $W\in\mathfrak M$ with
$W\le\mathcal{B} W$ satisfies $W\le V$, and $\mathcal{B}^jW\to V$ uniformly whenever $\mathcal{B}^jW\in\mathfrak M$ for all $j\ge0$;
(iii) $V^{\pi}(x_0)\ge\mathbb{E}[\ell(x_0,\bm{x}_1,\bm{\xi}_1)+\beta V(\bm{x}_1)]\ge V(x_0)$ for every policy $\pi$, also conditionally on
a $\sigma$-field independent of the noise on which $\pi$ may depend (as $\pi^k$ depends on $\mathcal{A}_{k-1}$).

\label{thm:det}
Let \cref{ass:Sinf,ass:Oinf} and~\eqref{eq:setting:volume_growth} hold as in \cref{lem:pass}, with $\underline V^{0}\ge0$, and
let $\hat\rho$, $\hat\psi$, $\Gamma^\beta_k$ and $\bar M_U$ be as in \cref{sec:ih-lemmas,sec:ih-master}. Run variant~(D) with pass
length $H$; let $\varepsilon_H:=\beta^H\bar\ell/(1-\beta)$ and $\varsigma\in(0,1)$.
\begin{enumerate}[label=(\roman*),nosep]
\item $\mathbb{E}[\Phi^k-\Phi^{k-1}\mid\mathcal{A}_{k-1}]\ge\kappa\hat\psi\big((1-\beta)(G^k-\Gamma^\beta_k-\varepsilon_H)_+\big)$ for $k\ge1$, so
the sum over $k$ of the expectations of the right-hand sides is at most $\bar M_U$. If $\Gamma^\beta_k\le\Gamma^\beta$
(deterministic), then, for $\theta>0$ with $\varepsilon_H\le\varsigma\theta$ and $(1-\beta)\theta\le\hat\rho$,
\begin{equation}\label{eq:appD:deterministic_rate}
\mathbb{E}\,\#\{k\ge1:G^k>\theta+\Gamma^\beta\}\le\frac{2(d+1)\,\bar M_U\,\hat\rho^d}{\kappa(1-\varsigma)^{d+1}(1-\beta)^{d+1}\theta^{d+1}};
\end{equation}
for $\delta\in(0,1]$, with probability at least $1-\delta$, simultaneously for all $\theta$ with
$\varepsilon_H\le\varsigma\theta$, $\#\{k\ge1:G^k>\theta+\Gamma^\beta_k\}\le9\ln(3/\delta)\,\bar M_U/(\kappa\hat\psi((1-\varsigma)(1-\beta)\theta))$.
\item For $\Gamma^\beta_k\le\Gamma^\beta$, $0<\theta<\bar\ell/(1-\beta)$ with $(1-\beta)\theta\le\hat\rho$ and
$H:=\big\lceil\ln\big((d+2)\bar\ell/((1-\beta)\theta)\big)/(1-\beta)\big\rceil$,
\begin{equation}\label{eq:appD:deterministic_rate_tuned}
\mathbb{E}\,\#\{k\ge1:G^k>\theta+\Gamma^\beta\}\le\frac{2e\,(d+1)\,\bar M_U\,\hat\rho^d}{\kappa(1-\beta)^{d+1}\theta^{d+1}},
\end{equation}
which is at most $2e(d+1)\bar\ell(4\hat L D)^d/(\kappa(1-\beta)^{d+2}\theta^{d+1})$ if $\bar M_U\le\bar\ell/(1-\beta)$, and the expected number
of cuts (trial-point cuts; the optional cuts of~\ref{OI4} are not counted) before the first iteration with $G^k\le\theta+\Gamma^\beta$ is at most $H$ times~\eqref{eq:appD:deterministic_rate_tuned}.
\end{enumerate}

\label{lem:slope}
Assume \ref{I1} and \ref{Ieta}. Let $W:X\to[0,\infty)$ be convex and bounded, $x\in X$, and $f$ affine
with $f\le\mathcal{B} W$ on $X_\eta$ and $f(x)=\mathcal{B} W(x)$. Let $\Theta:=\sup_{z\inX_\eta}\mathcal{B} W(z)-\mathcal{B} W(x)$. Then $f$ is
$(\Theta/\eta)$-Lipschitz on $\operatorname{aff} X$. Moreover:
\begin{enumerate}[label=(\roman*),nosep]
\item $\Theta\le\bar\ell+\beta\,(\sup_X W-\inf_X W)$;
\item under $(R_{1,0})$ (\cref{def:reach}), $\Theta\le\bar\ell$;
\item if $W\le\mathcal{B} W$ on $X$, $W$ is $L_W$-Lipschitz on $X$ and $(R_{m,\chi})$ holds, then
$\Theta\le m\bar\ell+\beta L_W\chi$.
\end{enumerate}
